+static const char *
+cf_state_to_string(file_state state)
+{
+    switch (state) {
+    case FILE_CLOSED:           return "closed";
+    case FILE_READ_PENDING:     return "read_pending";
+    case FILE_READ_IN_PROGRESS: return "reading";
+    case FILE_READ_ABORTED:     return "aborted";
+    case FILE_READ_DONE:        return "done";
+    default:                    return "unknown";
+    }
+}
+
+WSLUA_FUNCTION wslua_get_capture_file_info(lua_State *L) { /*
+    Returns a table describing the capture file currently open in the host
+    application, or nil if no file is loaded. This is a snapshot taken at
+    call time.
+
+    The table has the following fields:
+
+     * "path" - absolute path to the file (string, absent for unsaved captures)
+     * "type" - short file type name (string)
+     * "type_description" - human-readable file type (string)
+     * "encap" - short link-layer encapsulation name (string)
+     * "encap_description" - human-readable encapsulation (string)
+     * "compression" - compression type name (string)
+     * "size" - file size in bytes (integer, absent if unavailable, e.g. pipe captures after read)
+     * "snaplen" - snapshot length in bytes, 0 if unknown (integer)
+     * "packet_count" - total number of frames (integer)
+     * "state" - file state string (string)
+     * "is_tempfile" - true if this is an unsaved temporary file (boolean)
+     * "unsaved_changes" - true if there are unsaved edits (boolean)
+
+    @since 4.7.0
+    */
+    capture_file *cf = wslua_get_capture_file();
+    if (!cf || cf->state == FILE_CLOSED || !cf->provider.wth) {
+        lua_pushnil(L);
+        WSLUA_RETURN(1);
+    }
+
+    lua_newtable(L);
+
+    if (cf->filename && !cf->is_tempfile && strcmp(cf->filename, "-") != 0) {
+        char *abs = g_canonicalize_filename(cf->filename, NULL);
+        lua_pushstring(L, abs);
+        lua_setfield(L, -2, "path");
+        g_free(abs);
+    }
+
+    lua_pushstring(L, wtap_file_type_subtype_name(cf->cd_t));
+    lua_setfield(L, -2, "type");
+
+    lua_pushstring(L, wtap_file_type_subtype_description(cf->cd_t));
+    lua_setfield(L, -2, "type_description");
+
+    int encap = wtap_file_encap(cf->provider.wth);
+    lua_pushstring(L, wtap_encap_name(encap));
+    lua_setfield(L, -2, "encap");
+
+    lua_pushstring(L, wtap_encap_description(encap));
+    lua_setfield(L, -2, "encap_description");
+
+    ws_compression_type compression = wtap_get_compression_type(cf->provider.wth);
+    const char *compression_name = ws_compression_type_name(compression);
+    lua_pushstring(L, compression_name ? compression_name : "none");
+    lua_setfield(L, -2, "compression");
+
+    int64_t file_size = wtap_file_size(cf->provider.wth, NULL);
+    if (file_size >= 0) {
+        lua_pushinteger(L, (lua_Integer)file_size);
+        lua_setfield(L, -2, "size");
+    }
+
+    lua_pushinteger(L, (lua_Integer)cf->snap);
+    lua_setfield(L, -2, "snaplen");
+
+    lua_pushinteger(L, (lua_Integer)cf->count);
+    lua_setfield(L, -2, "packet_count");
+
+    lua_pushstring(L, cf_state_to_string(cf->state));
+    lua_setfield(L, -2, "state");
+
+    lua_pushboolean(L, cf->is_tempfile);
+    lua_setfield(L, -2, "is_tempfile");
+
+    lua_pushboolean(L, cf->unsaved_changes);
+    lua_setfield(L, -2, "unsaved_changes");
+
+    WSLUA_RETURN(1); /* Table with capture file info, or nil. */
+}
